\set ON_ERROR_STOP on
begin;
create function pg_temp.catalog_assert(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',message;end if;end$$;
create function pg_temp.catalog_denied(statement text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege or raise_exception or unique_violation or invalid_text_representation then return;end;raise exception 'FAIL: forbidden catalog operation succeeded';end$$;
insert into auth.users(id) values('88888888-8888-4888-8888-888888888888'),('99999999-9999-4999-8999-999999999999'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),('cccccccc-cccc-4ccc-8ccc-cccccccccccc');
insert into public.tasteprint_catalog_roles values('88888888-8888-4888-8888-888888888888','contributor'),('99999999-9999-4999-8999-999999999999','contributor'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','reviewer'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','publisher');
select pg_temp.catalog_assert(not has_table_privilege('authenticated','public.tasteprint_catalog_roles','INSERT'),'no role escalation');
select pg_temp.catalog_assert(not has_table_privilege('authenticated','public.tasteprint_catalog_entries','SELECT'),'no raw draft directory');
select pg_temp.catalog_assert(not has_function_privilege('anon','public.tasteprint_save_catalog_entry(jsonb,integer)','EXECUTE'),'no anonymous authoring');
select public.tasteprint_catalog_source_key('https://EXAMPLE.invalid/source/?utm_source=x&b=2&a=1#tracking') as canonical \gset
select pg_temp.catalog_assert(:'canonical'='https://example.invalid/source?a=1&b=2','canonical tracking/fragment/order/host/trailing-slash deduplication');
select jsonb_build_object('id','synthetic-listing','title','Synthetic listing','description','A synthetic editorial test listing.','category','activity','tags',jsonb_build_array('art'),'attributes',jsonb_build_object('curiosity',70),'revision',1,'status','active','source',jsonb_build_object('url','https://example.invalid/source/','publisher','Synthetic publisher','note','Synthetic source check only; no real listing.','verified_at',now()-interval '1 hour'),'constraints','{}'::jsonb,'availability',jsonb_build_object('status','unknown')) as item \gset
set role authenticated;
select set_config('request.jwt.claim.sub','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
select pg_temp.catalog_assert(public.tasteprint_my_catalog_entries()->'role'='null'::jsonb,'unassigned account receives no role');
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',:'item'));
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select pg_temp.catalog_assert(public.tasteprint_save_catalog_entry(:'item',0)=1,'author creates draft');
select pg_temp.catalog_assert(public.tasteprint_my_catalog_entries()->'entries'->0->>'own'='true','own draft visible');
select pg_temp.catalog_assert(not (public.tasteprint_my_catalog_entries()->'entries'->0 ? 'author_id'),'projection omits author identity');
select pg_temp.catalog_assert(public.tasteprint_published_catalog()='[]'::jsonb,'draft never public');
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',:'item'));
select pg_temp.catalog_assert(public.tasteprint_review_catalog_entry('synthetic-listing',1,'submit')=2,'author submits');
reset role;
update public.tasteprint_catalog_roles set role='admin' where user_id='88888888-8888-4888-8888-888888888888';
set role authenticated;
select pg_temp.catalog_denied($q$select public.tasteprint_review_catalog_entry('synthetic-listing',2,'approve','Admin cannot approve own work')$q$);
reset role;
update public.tasteprint_catalog_roles set role='contributor' where user_id='88888888-8888-4888-8888-888888888888';
set role authenticated;
select pg_temp.catalog_denied($q$select public.tasteprint_review_catalog_entry('synthetic-listing',2,'approve','Self approval')$q$);
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select pg_temp.catalog_assert(public.tasteprint_my_catalog_entries()->'entries'='[]'::jsonb,'other contributor has no draft access');
select pg_temp.catalog_denied($q$select public.tasteprint_catalog_entry_history('synthetic-listing')$q$);
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,2)',jsonb_set(:'item','{revision}','2')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(jsonb_set(:'item','{id}','"duplicate-source"'),'{source,url}','"https://EXAMPLE.invalid/source?utm_source=test#tracking"')));
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select pg_temp.catalog_assert(jsonb_array_length(public.tasteprint_my_catalog_entries()->'entries')=1,'reviewer sees submitted queue');
select pg_temp.catalog_denied($q$select public.tasteprint_review_catalog_entry('synthetic-listing',1,'approve','Old revision')$q$);
select pg_temp.catalog_denied($q$select public.tasteprint_review_catalog_entry('synthetic-listing',2,'approve','')$q$);
select pg_temp.catalog_assert(public.tasteprint_review_catalog_entry('synthetic-listing',2,'approve','Checked synthetic reference')=3,'separate reviewer approves');
select pg_temp.catalog_assert(public.tasteprint_published_catalog()='[]'::jsonb,'approval alone is not publication');
select pg_temp.catalog_denied($q$select public.tasteprint_review_catalog_entry('synthetic-listing',3,'publish')$q$);
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select pg_temp.catalog_assert(public.tasteprint_review_catalog_entry('synthetic-listing',3,'publish')=4,'publisher releases approved version');
select pg_temp.catalog_assert(jsonb_array_length(public.tasteprint_published_catalog())=1,'only published item public');
select pg_temp.catalog_assert(public.tasteprint_published_catalog('synthetic-listing',1)='[]'::jsonb,'keyset pagination advances');
reset role;
update public.tasteprint_catalog_entries set item=jsonb_set(item,'{source,verified_at}',to_jsonb((now()-interval '31 days')::text)) where id='synthetic-listing';
set role anon;
select pg_temp.catalog_assert(public.tasteprint_published_catalog()='[]'::jsonb,'stale listings are excluded, never silently reverified');
reset role;
update public.tasteprint_catalog_entries set item=:'item' where id='synthetic-listing';
set role authenticated;
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
set role anon;
select pg_temp.catalog_assert(jsonb_array_length(public.tasteprint_published_catalog())=1,'anonymous public projection works');
select pg_temp.catalog_denied($q$select * from public.tasteprint_catalog_history$q$);
set role authenticated;
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select pg_temp.catalog_assert(public.tasteprint_save_catalog_entry(jsonb_set(:'item','{revision}','2'),4)=5,'editing resets review and publication');
select pg_temp.catalog_assert(public.tasteprint_published_catalog()='[]'::jsonb,'edited listing removed from public projection');
select pg_temp.catalog_assert(jsonb_array_length(public.tasteprint_catalog_entry_history('synthetic-listing'))=5,'history records exact workflow versions');
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,5)',jsonb_set(:'item','{revision}','2')||'{"private_user_id":"not-allowed"}'::jsonb));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,5)',jsonb_set(jsonb_set(:'item','{revision}','3'),'{source,url}','"javascript:alert(1)"')));
-- Unique candidate source ensures duplicate checks cannot mask validation failures.
select jsonb_set(jsonb_set(:'item','{id}','"invalid-candidate"'),'{source,url}','"https://example.invalid/invalid-candidate"') as candidate \gset
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{tags}','[]')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',:'candidate'::jsonb-'constraints'));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{revision}','null')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{attributes}','{"private_metric":50}')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{constraints}','{"cost":1e309,"currency":"USD"}')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{constraints}','{"currency":23}')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{source,url}','"https://example.invalid:99999/invalid-candidate"')));
select pg_temp.catalog_denied(format('select public.tasteprint_save_catalog_entry(%L::jsonb,0)',jsonb_set(:'candidate','{source,verified_at}',to_jsonb((now()+interval '1 day')::text))));
select pg_temp.catalog_assert(public.tasteprint_review_catalog_entry('synthetic-listing',5,'withdraw','Remove synthetic listing')=6,'author withdraws');
select pg_temp.catalog_assert(public.tasteprint_review_catalog_entry('synthetic-listing',6,'remove')=0,'author removes withdrawn record and history');
reset role;
select pg_temp.catalog_assert((select count(*) from public.tasteprint_catalog_history)=0,'history cascades only on explicit removal');
rollback;
\echo 'Catalog contributor SQL PASS: no default roles/escalation/raw access, separate author/reviewer/publisher, exact-version updates, source deduplication, draft/private metadata exclusion, public pagination, approval reset, history and withdrawal/removal.'
